import { useEffect, useMemo, useState } from 'react';
import { assetUrl } from '../../utils/assets';
import { KIND_COLOR, type AuthoredObject } from '../AuthoredObjectOverlay';

/**
 * What the ORIGINAL authors into this room — the measured side of the field
 * generator, listed so it can be checked against the geometry in the viewport.
 *
 * The point of this tab is sanity-checking a definition, not editing one:
 * everything here comes from psz-re and is regenerated by
 * scripts/tools/refield/import_re_objects.py. Editing belongs upstream.
 */

interface Props {
  stageId: string;
  visibleKinds: string[] | null;
  setVisibleKinds: (kinds: string[] | null) => void;
}

interface RoomEntry {
  groups?: number[] | null;
  objects: AuthoredObject[];
}

export default function AuthoredTab({ stageId, visibleKinds, setVisibleKinds }: Props) {
  const [rooms, setRooms] = useState<Record<string, RoomEntry> | null>(null);

  useEffect(() => {
    fetch(assetUrl('/data/re_reference/room_objects.json'))
      .then((r) => (r.ok ? r.json() : null))
      .then((d) => setRooms(d?.rooms ?? null))
      .catch(() => setRooms(null));
  }, []);

  const entry = rooms?.[`${stageId}_d`];
  const byKind = useMemo(() => {
    const out: Record<string, number> = {};
    for (const o of entry?.objects ?? []) out[o.k] = (out[o.k] ?? 0) + 1;
    return out;
  }, [entry]);

  const byGroup = useMemo(() => {
    const out: Record<string, number> = {};
    for (const o of entry?.objects ?? []) {
      const g = o.g === null || o.g === undefined ? 'ungrouped' : String(o.g);
      out[g] = (out[g] ?? 0) + 1;
    }
    return out;
  }, [entry]);

  const kinds = Object.keys(byKind).sort();

  return (
    <div style={{ padding: 16, color: '#e8e8f0', fontSize: 13, lineHeight: 1.5 }}>
      <h3 style={{ margin: '0 0 4px' }}>Authored objects</h3>
      <div style={{ color: '#8a90b8', fontSize: 11, marginBottom: 12 }}>
        Measured, from psz-re's per-room object table. Room-local coordinates in
        the same frame as the doorways, plus a 16-bit facing. Read-only — this is
        the original's data, regenerated by <code>import_re_objects.py</code>.
      </div>

      {!rooms && <div style={{ color: '#8a90b8' }}>Loading…</div>}
      {rooms && !entry && (
        <div style={{ color: '#e0c97a' }}>
          No authored objects for <code>{stageId}_d</code>. City stages and a few
          field rooms carry none in set <code>d</code>.
        </div>
      )}

      {entry && (
        <>
          <div style={{ marginBottom: 12 }}>
            <strong>{entry.objects.length}</strong> objects
            {entry.groups && (
              <span style={{ color: '#8a90b8' }}>
                {' '}· group sizes [{entry.groups.join(', ')}]
              </span>
            )}
          </div>

          {/* A room never builds all of this at once, and the group is the only
              thing that says which subset arrives together. */}
          <div style={{ marginBottom: 12, fontSize: 11, color: '#8a90b8' }}>
            by group:{' '}
            {Object.entries(byGroup)
              .sort()
              .map(([g, n]) => `${g}:${n}`)
              .join('  ')}
            <div style={{ marginTop: 4 }}>
              One of five layout masks picks which of groups 0–4 are built; group
              5 is rolled 0–3 at 40/20/20/20, so 40% of visits take nothing from
              it. What you see here is the table, not a single visit.
            </div>
          </div>

          <div style={{ marginBottom: 8 }}>
            <button
              onClick={() => setVisibleKinds(null)}
              style={{
                background: visibleKinds === null ? '#2a2a4a' : '#12122a',
                color: '#e8e8f0',
                border: '1px solid #2a2a4a',
                borderRadius: 4,
                padding: '3px 8px',
                fontSize: 11,
                cursor: 'pointer',
                marginRight: 6,
              }}
            >
              show all
            </button>
            {kinds.map((k) => {
              const on = visibleKinds === null || visibleKinds.includes(k);
              return (
                <button
                  key={k}
                  onClick={() =>
                    setVisibleKinds(
                      visibleKinds === null
                        ? kinds.filter((x) => x !== k)
                        : on
                          ? visibleKinds.filter((x) => x !== k)
                          : [...visibleKinds, k],
                    )
                  }
                  style={{
                    background: on ? '#1a1a2e' : '#0f0f1e',
                    color: on ? KIND_COLOR[k] ?? '#e8e8f0' : '#555',
                    border: `1px solid ${on ? KIND_COLOR[k] ?? '#2a2a4a' : '#2a2a4a'}`,
                    borderRadius: 4,
                    padding: '3px 8px',
                    fontSize: 11,
                    cursor: 'pointer',
                    margin: '0 6px 6px 0',
                  }}
                >
                  {k} {byKind[k]}
                </button>
              );
            })}
          </div>
        </>
      )}
    </div>
  );
}
